let a = 5;
let b = a;
b = 10;
console.log(a); // 5 - oryginal niezmieniony

const arr1 = [1, 2, 3];
const arr2 = arr1;    // arr2 wskazuje NA TO SAMO miejsce w pamieci
arr2.push(4);
console.log(arr1);    // [1, 2, 3, 4] - oryginal zmieniony!

// Jak SKOPIOWAC tablice naprawde? Operator spread:
const arr3 = [...arr1];
arr3.push(99);
console.log(arr1);    // [1, 2, 3, 4] - TERAZ oryginal bezpieczny

const userA = { name: "Anna", address: { city: "Poznań" } };
const userB = { ...userA }; // shallow copy

userB.name = "Basia";
userB.address.city = "Gdańsk"; // BLEDNIE modyfikuje address w OBU obiektach!

console.log(userA.name);          // "Anna" - OK, niezalezne
console.log(userA.address.city);  // "Gdańsk" - NIE OK! to wciaz ta sama referencja

const userA = { name: "Anna", address: { city: "Poznań" } };
const userB = {
  ...userA,
  address: { ...userA.address } // jawna, OSOBNA kopia zagniezdzonego obiektu
};

userB.address.city = "Gdańsk";
console.log(userA.address.city); // "Poznań" - POPRAWNIE niezmienione

