let punkty = 100;
let punktyKopia = punkty;
punktyKopia = 50;

console.log(punkty);       // 100 - niezmienione
console.log(punktyKopia);  // 50

const owoce = ["jablko", "banan"];
const owoce2 = owoce;
owoce2.push("gruszka");

console.log(owoce); // ['jablko', 'banan', 'gruszka']
// owoce ZOSTALA zmieniona, mimo ze modyfikowalismy owoce2 - obie
// zmienne wskazuja na TA SAMA tablice w pamieci (typ referencyjny)

const liczby = [1, 2, 3];
const liczby2 = [...liczby];
liczby2.push(4);

console.log(liczby); // [1, 2, 3] - NIEZMIENIONE
console.log(liczby2); // [1, 2, 3, 4]

const auto = { marka: "Toyota", silnik: { moc: 120 } };
const auto2 = { ...auto };
auto2.marka = "Honda";

console.log(auto.marka); // "Toyota" - niezmienione

const auto = { marka: "Toyota", silnik: { moc: 120 } };
const auto2 = { ...auto };
auto2.silnik.moc = 150;

console.log(auto.silnik.moc); // 150 - ZMIENIONE! mimo ze modyfikowalismy auto2
// spread to KOPIA PLYTKA (shallow) - wlasciwosc 'silnik' na najwyzszym
// poziomie zostala skopiowana, ale JEJ WARTOSC (zagniezdzony obiekt)
// to WCIAZ REFERENCJA do TEGO SAMEGO obiektu co w auto

function zmienNazwe(obiekt) {
  obiekt.nazwa = "Zmieniono";
}

const moj = { nazwa: "Stare" };
zmienNazwe(moj);
console.log(moj); // { nazwa: 'Zmieniono' } - ZMIENIONY, mimo braku return

const firma = { nazwa: "TechCorp", adres: { miasto: "Warszawa", kod: "00-001" } };
const kopia = { ...firma, adres: { ...firma.adres } };

kopia.adres.miasto = "Krakow";
console.log(firma.adres.miasto); // "Warszawa" - POPRAWNIE niezmienione
console.log(kopia.adres.miasto); // "Krakow"

function saTaSamaTablica(a, b) {
  return a === b;
}

console.log(saTaSamaTablica([1, 2, 3], [1, 2, 3])); // false - DWIE osobne tablice

const x = [1, 2, 3];
const y = x;
console.log(saTaSamaTablica(x, y)); // true - TA SAMA tablica

let temperatura = 20.5;
let kopiaTemperatury = temperatura;
kopiaTemperatury = 30.0;

console.log(temperatura);       // 20.5
console.log(kopiaTemperatury);  // 30
